<script setup lang="ts">
import {nextTick,onMounted,reactive,ref} from 'vue'
import {scheduleApi} from '../schedules'
import {dismissAfterFourSeconds} from '../temporary-message'
const emit=defineEmits<{saving:[value:boolean]}>(),items=ref<any[]>([]),busy=ref(false),error=ref(''),message=ref(''),dialog=ref<HTMLDialogElement|null>(null),formError=ref('')
const form=reactive({id:0,title:'',message:'',starts_on:'',ends_on:'',published:false,version:0});dismissAfterFourSeconds(message)
async function load(){try{items.value=(await scheduleApi('admin/notices')).notices}catch(e){error.value=e instanceof Error?e.message:'Unable to load notices.'}}
async function open(item:any=null){const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kathmandu',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());Object.assign(form,item??{id:0,title:'',message:'',starts_on:date,ends_on:date,published:false,version:0});formError.value='';await nextTick();dialog.value?.showModal()}
function close(){if(!busy.value)dialog.value?.close()}
async function save(){if(busy.value)return;busy.value=true;emit('saving',true);formError.value='';try{message.value=(await scheduleApi('admin/notices'+(form.id?'/'+form.id:''),form.id?'PUT':'POST',{...form,published:Boolean(form.published)})).message;await load();dialog.value?.close()}catch(e){formError.value=e instanceof Error?e.message:'Unable to save notice.'}finally{busy.value=false;emit('saving',false)}}
onMounted(load)
</script>
<template><section class="card"><div class="heading"><div><p class="eyebrow">SCHOOL COMMUNICATION</p><h2>School notices</h2></div><div class="heading-actions"><button type="button" @click="open()">Create notice</button><button type="button" class="secondary" @click="load">Refresh notices</button></div></div><p class="muted">Students and parents see published notices only during their display dates. Use a draft to withdraw a notice.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><p v-if="!items.length" class="muted">No school notices yet.</p><article v-for="item in items" :key="item.id" class="notice-row"><div><h3>{{item.title}}</h3><p>{{item.starts_on}} — {{item.ends_on}} · {{item.published?'Published':'Draft'}}</p></div><button type="button" class="secondary" @click="open(item)">Edit notice</button></article><dialog ref="dialog" class="account-create-dialog" aria-labelledby="notice-title" @cancel.prevent="close"><div class="heading"><h2 id="notice-title">{{form.id?'Edit notice':'Create notice'}}</h2><button type="button" class="secondary" :disabled="busy" @click="close">Close</button></div><p v-if="formError" class="error" role="alert">{{formError}}</p><form @submit.prevent="save"><fieldset :disabled="busy"><label>Title<input v-model="form.title" required maxlength="150"></label><label>Message<textarea v-model="form.message" required maxlength="4000" rows="5"></textarea></label><div class="fields"><label>Show from<input v-model="form.starts_on" type="date" required></label><label>Show until<input v-model="form.ends_on" type="date" :min="form.starts_on" required></label></div><label class="check"><input v-model="form.published" type="checkbox">Publish for students and parents</label><div class="popup-actions"><button>{{busy?'Saving…':'Save notice'}}</button><button type="button" class="secondary" @click="close">Cancel</button></div></fieldset></form></dialog></section></template>
<style scoped>
.heading h2{margin:0}.notice-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-top:1px solid #dce6df}.notice-row h3{font-size:15px}.notice-row p{font-size:12px;color:#63776b}.notice-row button{min-height:44px;font-size:13px}fieldset{border:0;padding:0;min-width:0}label{margin:14px 0;font-size:13px}label input,label textarea{margin-top:6px;display:block;width:100%}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.check{display:flex;align-items:center;gap:8px}.check input{width:18px;height:18px;margin:0}.popup-actions{margin-top:18px}textarea{resize:vertical}@media(max-width:400px){.fields{grid-template-columns:1fr}.notice-row{flex-wrap:wrap}}
</style>
